  return (
    <DialogCombobox componentId={componentId} label={label} value={selectedValue ? [selectedValue] : []}>
      <DialogComboboxTrigger aria-label={label} allowClear={false} disabled={disabled} />
      <DialogComboboxContent>
        <DialogComboboxOptionList>
          {options.map((option) => (
            <DialogComboboxOptionListSelectItem
              key={option}
              value={option}
              checked={selectedValue === option}
              onChange={() => onChange(option)}
            >
              {option}
            </DialogComboboxOptionListSelectItem>
          ))}
        </DialogComboboxOptionList>
      </DialogComboboxContent>
    </DialogCombobox>
  );
};
